import React from 'react';

import Sunglasses from '@pohodnik/icons/svg/RealWorld/Sunglasses';

import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import Empty from '@ui-kit/Empty';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import style from './modal.module.less';
import { getEquipItems, IGetEquipCriteria } from '../../../@services/equip.service';
import { IEquip } from '../../../@types/equip.types';
import { addEquipModal } from '../addEquip/addEduipModal';
import EquipOptionsWidget from '../components/EquipOptionsWidget';

interface IAddEquipToSetModalProps {
  selectedIds?: number[];
  onSelect: (equip: IEquip[]) => void;
  filter?: IGetEquipCriteria;
}

interface IEquipWithSelected extends IEquip {
  selected: boolean;
}

const AddEquipToSetModal: React.FC<IAddEquipToSetModalProps> = ({
  selectedIds = [],
  onSelect,
  filter,
}) => {
  const [list, setList] = React.useState<IEquipWithSelected[]>([]);
  const [searchString, setSearchString] = React.useState('');

  const handleSearch = (val: string = '') => {
    setSearchString(val);
  };

  React.useEffect(() => {
    const init = async () => {
      const eq = await getEquipItems(filter);
      setList(eq.map((i) => ({ ...i, selected: selectedIds.includes(i.id) })));
    };

    init().catch(err);
  }, [selectedIds, filter]);

  const handleCheck = (item: IEquipWithSelected) => (selected: boolean) => {
    setList(list.map((i) => (i.id === item.id ? { ...i, selected } : i)));
  };

  const handleAddEquip = () => {
    addEquipModal((added) => {
      setList([...list, { ...added, selected: true }]);
    });
  };

  if (list == null) {
    return <PageLoader />;
  }

  const handleSave = () => {
    const selectedItems = list.filter(({ selected }) => selected);
    onSelect(selectedItems);
  };

  const selectedItems = list.filter(({ selected = false }) => selected);

  const aggregator = selectedItems.reduce(
    (acc, cur) =>
      Object.assign(
        acc,
        +cur.is_group === 1
          ? {
              groupWeight: acc.groupWeight + +cur.weight,
              groupValue: acc.groupValue + +cur.value,
            }
          : {
              weight: acc.weight + +cur.weight,
              value: acc.value + +cur.value,
            },
      ),
    { weight: 0, value: 0, groupWeight: 0, groupValue: 0 },
  );

  return (
    <PohRow className={style.modalContent}>
      <PohCol md={8} xs={12} className={style.list}>
        {!list?.length && (
          <Empty>
            <div className="text-center">
              <p>
                Похоже вы еще не добавляли своё снаряжение.
                <br />
                Самое время сделать это!
              </p>
              <PohButton onClick={handleAddEquip}>Добавить новое снаряжение</PohButton>
            </div>
          </Empty>
        )}
        {!!list.length && (
          <PohList
            data={list
              .filter(
                (i) =>
                  !searchString?.length ||
                  i.name.toLowerCase().includes(searchString.toLowerCase()),
              )
              .map((item) => ({
                key: item.id,
                content: (
                  <label className="m-0 d-flex align-items-center justify-content-between equip-item">
                    <PohCheckbox
                      onChange={handleCheck(item)}
                      checked={item.selected}
                      label={item.name}
                    />
                    <div className="d-flex align-items-center flex-nowrap me-n2">
                      <EquipOptionsWidget
                        weight={round(item.weight / 1000)}
                        value={round(+item.value)}
                      />
                      <PohAva src={item.photo} alt={item.name} width={32} icon={<Sunglasses />} />
                    </div>
                  </label>
                ),
              }))}
          />
        )}
      </PohCol>
      <PohCol
        md={4}
        xs={12}
        className="border-start d-flex flex-wrap justify-content-between flex-column"
      >
        <aside>
          <PohInput
            type={InputTypes.search}
            className="mb-2"
            placeholder="Найти в списке"
            onChange={handleSearch}
            value={searchString}
            autoFocus={list?.length > 5}
            disabled={!list?.length}
          />
          <PohButton
            onClick={handleAddEquip}
            variant={ButtonVariant.Light}
            className="d-block w-100 mb-4"
          >
            Добавить новое
          </PohButton>

          <h5 className="d-flex align-items-center justify-content-between">
            Выбрано
            <PohBadge
              rounded
              variant={selectedItems.length > 0 ? BadgeVariant.Primary : BadgeVariant.Light}
            >
              {selectedItems.length}
            </PohBadge>
          </h5>
          <table className="table table-sm table-striped">
            <tbody>
              {!filter?.is_group && (
                <tr>
                  <td>Личное</td>
                  <td className="text-end">
                    <b>{round(aggregator.weight / 1000)}</b>&thinsp;кг
                  </td>
                  <td className="text-end">
                    <b>{round(aggregator.value)}</b>&thinsp;л&nbsp;
                  </td>
                </tr>
              )}
              {!filter?.is_group && (
                <tr>
                  <td>Групповое</td>
                  <td className="text-end">
                    <b>{round(aggregator.groupWeight / 1000)}</b>&thinsp;кг
                  </td>
                  <td className="text-end">
                    <b>{round(aggregator.groupValue)}</b>&thinsp;л&nbsp;
                  </td>
                </tr>
              )}
            </tbody>
            <tfoot>
              <tr>
                <td>Всего</td>
                <td className="text-end">
                  <b>{round((aggregator.weight + aggregator.groupWeight) / 1000)}</b>&thinsp;кг
                </td>
                <td className="text-end">
                  <b>{round(aggregator.value + aggregator.groupValue)}</b>&thinsp;л&nbsp;
                </td>
              </tr>
            </tfoot>
          </table>
        </aside>
        <footer className="d-flex justify-content-end">
          <PohButton
            onClick={handleSave}
            disabled={!selectedItems?.length}
            variant={ButtonVariant.Success}
          >
            Сохранить выбранное
          </PohButton>
        </footer>
      </PohCol>
    </PohRow>
  );
};

export default AddEquipToSetModal;
