import React from 'react';

import { IGetEquipCriteria } from '@apps/Hiking/@services/equip.service';
import { showModal } from '@ui-kit/Modal';

import AddEquipToSetModal from './AddEquipToSetModal';
import { IEquip } from '../../../@types/equip.types';

export function addEquipToSetModal(
  onSelect: (equip: IEquip[]) => void,
  selectedIds: number[] = [],
  filter?: IGetEquipCriteria,
) {
  showModal({
    size: 'sm',
    children: (closeHandler: () => void) => (
      <AddEquipToSetModal
        filter={filter}
        selectedIds={selectedIds}
        onSelect={(selectedItems) => {
          onSelect(selectedItems);
          closeHandler();
        }}
      />
    ),
  });
}

export default { addEquipToSetModal };
